class Solution {
  public int longestRepeatingSubstring(String s) {
    int n = s.length(), best = 0;
    int[] dp = new int[n + 1]; // dp[j]: length of the common suffix ending at i and j
    for (int i = 1; i <= n; i++) {
      for (int j = i - 1; j >= 1; j--) {
        dp[j] = s.charAt(i - 1) == s.charAt(j - 1) ? dp[j - 1] + 1 : 0;
        best = Math.max(best, dp[j]);
      }
    }
    return best;
  }
}
